def main():
    import sys
    data = sys.stdin.read().split()
    idx = 0
    N = int(data[idx]); idx+=1
    K = int(data[idx]); idx+=1
    requests = []
    for _ in range(N):
        requests.append(int(data[idx])); idx+=1

    center = (K+1)//2
    occupied = [[False]*(K+2) for _ in range(K+2)]

    out = []
    for M in requests:
        best = None
        for x in range(1, K+1):
            for yl in range(1, K-M+2):
                yr = yl + M - 1
                # check free
                free = True
                for y in range(yl, yr+1):
                    if occupied[x][y]:
                        free = False
                        break
                if not free:
                    continue
                val = 0
                for y in range(yl, yr+1):
                    val += abs(x-center) + abs(y-center)
                key = (val, x, yl)
                if best is None or key < best[0]:
                    best = (key, x, yl, yr)
        if best is None:
            out.append("-1")
        else:
            _, x, yl, yr = best
            for y in range(yl, yr+1):
                occupied[x][y] = True
            out.append(f"{x} {yl} {yr}")

    print("\n".join(out))

main()

