import sys, math

def is_composite(n: int) -> bool:
    if n < 4:
        return False
    if n % 2 == 0:
        return True
    if n % 3 == 0:
        return True
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return True
        i += 6
    return False

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])

    # Try b = 4, 6, 8, 9, ... (composite numbers)
    # and check if a = n + b is also composite
    composites = []
    for x in range(4, 200):
        if is_composite(x):
            composites.append(x)

    for b in composites:
        a = n + b
        if is_composite(a):
            sys.stdout.write(f"{a} {b}\n")
            return

if __name__ == "__main__":
    main()

