import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    positions = []
    for r in range(3):
        for c in range(3):
            cells = []
            for dr in range(2):
                for dc in range(2):
                    cells.append((r+dr)*4 + (c+dc))
            positions.append((r, c, cells))
    pos_index = {}
    for i,(r,c,cells) in enumerate(positions):
        pos_index[(r,c)] = i

    results = []
    while idx < len(data):
        N = int(data[idx]); idx += 1
        if N == 0:
            break
        schedule = []
        for _ in range(N):
            row = [int(data[idx+k]) for k in range(16)]
            idx += 16
            schedule.append(row)

        # state: (position_index, tuple of dry-counts for 16 cells)
        # initial: day 0 cloud at center (6-7-10-11) => position r=1,c=1
        # dry counts: number of consecutive days without rain, after day 0
        start_pos = pos_index[(1,1)]
        start_cells = set(positions[start_pos][2])
        # dry count: 0 if rained today else +1. Initially day before period rained everywhere.
        init_dry = []
        for cell in range(16):
            if cell in start_cells:
                init_dry.append(0)
            else:
                init_dry.append(1)
        # check day 0 schedule: markets must have sun (not rain)
        # day 0 (first day) schedule
        sched0 = schedule[0]
        valid = True
        for cell in range(16):
            if sched0[cell] == 1 and cell in start_cells:
                valid = False
                break
        for cell in range(16):
            if init_dry[cell] > 6:
                valid = False
                break
        if not valid:
            results.append(0)
            continue

        current = set()
        current.add((start_pos, tuple(init_dry)))

        # moves: stay, or move 1 or 2 in each direction
        moves = [(0,0)]
        for d in [1,2]:
            moves.append((-d,0))
            moves.append((d,0))
            moves.append((0,-d))
            moves.append((0,d))

        ok = True
        for day in range(1, N):
            sched = schedule[day]
            nxt = set()
            for (pi, dry) in current:
                r, c, _ = positions[pi]
                for (dr, dc) in moves:
                    nr, nc = r+dr, c+dc
                    if (nr,nc) not in pos_index:
                        continue
                    npi = pos_index[(nr,nc)]
                    ncells = set(positions[npi][2])
                    # check schedule: markets need sun
                    bad = False
                    for cell in ncells:
                        if sched[cell] == 1:
                            bad = True
                            break
                    if bad:
                        continue
                    new_dry = list(dry)
                    ok2 = True
                    for cell in range(16):
                        if cell in ncells:
                            new_dry[cell] = 0
                        else:
                            new_dry[cell] += 1
                            if new_dry[cell] > 6:
                                ok2 = False
                                break
                    if not ok2:
                        continue
                    nxt.add((npi, tuple(new_dry)))
            current = nxt
            if not current:
                ok = False
                break

        results.append(1 if (ok and current) else 0)

    print('\n'.join(map(str, results)))

main()

cc_p01676 Tree Reconstruction.code:
import sys

def solve():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    out_lines = []
    while True:
        try:
            N = int(next(it))
            M = int(next(it))
        except StopIteration:
            break
        adj = [[] for _ in range(N)]
        for _ in range(M):
            u = int(next(it)) - 1
            v = int(next(it)) - 1
            adj[u].append(v)
            adj[v].append(u)
        visited = [False]*N
        components = 0
        stack = []
        for i in range(N):
            if not visited[i]:
                components += 1
                stack.append(i)
                visited[i] = True
                while stack:
                    node = stack.pop()
                    for nb in adj[node]:
                        if not visited[nb]:
                            visited[nb] = True
                            stack.append(nb)
        answer = M - N + components
        out_lines.append(str(answer))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

