import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1].strip()
    pref = [0] * (n + 1)
    for i, ch in enumerate(s, 1):
        pref[i] = pref[i - 1] + (1 if ch == '(' else -1)

    total = pref[n]
    # suffix minima of pref
    suff_min = [0] * (n + 2)
    INF = 10**9
    suff_min[n] = pref[n]
    for i in range(n - 1, -1, -1):
        suff_min[i] = pref[i] if pref[i] < suff_min[i + 1] else suff_min[i + 1]

    # prefix minima up to each position
    pref_min = [0] * (n + 1)
    pref_min[0] = pref[0]
    for i in range(1, n + 1):
        pref_min[i] = pref[i] if pref[i] < pref_min[i - 1] else pref_min[i - 1]

    ans = 0
    if total == 2:
        # need to flip '(' to ')'
        for i, ch in enumerate(s, 1):
            if ch == '(':
                if pref_min[i - 1] >= 0 and suff_min[i] >= 2:
                    ans += 1
    elif total == -2:
        # need to flip ')' to '('
        for i, ch in enumerate(s, 1):
            if ch == ')':
                if pref_min[i - 1] >= 0 and suff_min[i] >= -2:
                    ans += 1
    # else ans stays 0
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    main()

