import sys

def minimal_number(s: str) -> str:
    if s == "0":
        return "0"
    digits = sorted(s)
    if digits[0] != '0':
        return ''.join(digits)
    # find first non-zero
    for i, d in enumerate(digits):
        if d != '0':
            # place this digit first, then all zeros, then rest
            first = d
            zeros = digits[:i]
            rest = digits[i+1:]
            return first + ''.join(zeros) + ''.join(rest)
    return ''.join(digits)  # all zeros, shouldn't happen except "0"

def main():
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        return
    n = data[0].strip()
    m = data[1].strip()
    correct = minimal_number(n)
    if m == correct:
        sys.stdout.write("OK")
    else:
        sys.stdout.write("WRONG_ANSWER")

if __name__ == "__main__":
    main()

