        n = int(next(it)); s = int(next(it)); t = int(next(it))
        if n == 0 and s == 0 and t == 0: break
        q = [0]*(n+1)
        for i in range(1,n+1): q[i] = int(next(it))
        w = [[0]*(n+1) for _ in range(n+1)]
        for i in range(1,n+1):
            for j in range(1,n+1): w[i][j] = int(next(it))
        adj = [[] for _ in range(n+1)]
        for i in range(1,n+1):
            for j in range(1,n+1):
                if w[i][j] > 0: adj[i].append((j, w[i][j]))
        INF = 1e100
        dist = [INF]*(n+1); dist[t] = 0.0
        pq = [(0.0, t)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]+1e-12: continue
            for v, wt in adj[u]:
                nd = d+wt
                if nd < dist[v]-1e-12: dist[v]=nd; heapq.heappush(pq,(nd,v))
        reachable = [dist[i]<INF/2 for i in range(n+1)]
        if not reachable[s]: out_lines.append("impossible"); continue
        # For unsigned nodes: if any neighbor is unreachable, this node is impossible
        # Propagate impossibility
        possible = list(reachable)
        changed = True
        while changed:
            changed = False
            for i in range(1,n+1):
                if not possible[i]: continue
                if i == t: continue
                if q[i] == 0:  # unsigned
                    for v,wt in adj[i]:
                        if not possible[v]:
                            possible[i] = False; changed = True; break
        if not possible[s]: out_lines.append("impossible"); continue
        nodes = [i for i in range(1,n+1) if possible[i] and i!=t]
        idx = {node:i for i,node in enumerate(nodes)}
        m = len(nodes)
        A = [[0.0]*(m+1) for _ in range(m)]
        impossible = False
        for node in nodes:
            i = idx[node]
            A[i][i] = 1.0
            if q[node]==1:
                lst = [(v,wt) for v,wt in adj[node] if abs(dist[node]-dist[v]-wt)<1e-9]
                if not lst: impossible=True; break
                k=len(lst); sumw=sum(wt for v,wt in lst)
                for v,wt in lst:
                    if v!=t: A[i][idx[v]] -= 1.0/k
                A[i][m] = sumw/k
            else:
                lst = adj[node]; k=len(lst); sumw=sum(wt for v,wt in lst)
                for v,wt in lst:
                    if v!=t: A[i][idx[v]] -= 1.0/k
                A[i][m] = sumw/k
        if impossible: out_lines.append("impossible"); continue
        eps=1e-12
        for col in range(m):
            pivot=col
            while pivot<m and abs(A[pivot][col])<eps: pivot+=1
            if pivot==m: impossible=True; break
            if pivot!=col: A[col],A[pivot]=A[pivot],A[col]
            piv=A[col][col]
            for j in range(col,m+1): A[col][j]/=piv
            for i in range(m):
                if i!=col:
                    f=A[i][col]
                    if abs(f)>eps:
                        for j in range(col,m+1): A[i][j]-=f*A[col][j]
        if impossible: out_lines.append("impossible"); continue
        Es=[0.0]*(n+1)
        for node in nodes: Es[node]=A[idx[node]][m]
        out_lines.append("{:.10f}".format(Es[s]))
    print("\n".join(out_lines))

