    C = [[0]*65 for _ in range(65)]
    for i in range(65):
        C[i][0] = C[i][i] = 1
        for j in range(1, i):
            C[i][j] = C[i-1][j-1] + C[i-1][j]
    return C

C = precompute_c()

def count_leq(N, k):
    if N < 0:
        return 0
    cnt = 0
    ones = 0
    for pos in range(63, -1, -1):
        if N >> pos & 1:
            # set this bit to 0, choose remaining bits
            rem = pos
            need = k - ones
            if 0 <= need <= rem:
                cnt += C[rem][need]
            ones += 1
            if ones > k:
                break
    else:
        if ones == k:
            cnt += 1
    return cnt

