    ops = []
    for _ in range(m):
        t = int(data[idx]); idx+=1
        l = int(data[idx]); idx+=1
        r = int(data[idx]); idx+=1
        x = int(data[idx]); idx+=1
        ops.append((t,l,r,x))

    INF = float('inf')
    # upper bound for each element
    ub = [INF]*(n+1)

    # For each type-2 op, compute the cumulative add at that time for each position
    # We'll process: a[j] <= m - (sum of d added up to that op affecting j)
    # Set a[j] as small as possible? Actually set ub[j] = min over constraints
    # Then a[j] = ub[j], and check max constraints are satisfied (equality).

    # First pass: compute add prefix
    add = [0]*(n+1)
    for (t,l,r,x) in ops:
        if t==1:
            for j in range(l,r+1):
                add[j]+=x
        else:
            # a[j] + add[j] <= x for j in [l,r], so a[j] <= x - add[j]
            for j in range(l,r+1):
                ub[j] = min(ub[j], x - add[j])

    # set a[j] = ub[j] if finite else 0 (some large but valid)
    a = [0]*(n+1)
    for j in range(1,n+1):
        if ub[j]==INF:
            a[j]=0
        else:
            a[j]=ub[j]

