import sys
from heapq import heappush, heappop

INF = 10**15

def solve():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    out_lines = []
    while True:
        N = int(next(it)); M = int(next(it))
        if N == 0 and M == 0: break
        land_adj = [[] for _ in range(N+1)]
        sea_adj = [[] for _ in range(N+1)]
        for _ in range(M):
            x=int(next(it)); y=int(next(it)); t=int(next(it)); sl=next(it)
            if sl=='L':
                land_adj[x].append((y,t)); land_adj[y].append((x,t))
            else:
                sea_adj[x].append((y,t)); sea_adj[y].append((x,t))
        R = int(next(it))
        seq = [int(next(it)) for _ in range(R)]
        # dp[ship_pos] = min cost, person is at seq[idx]
        dp = [INF]*(N+1)
        dp[seq[0]] = 0
        for idx in range(R-1):
            a = seq[idx]; b = seq[idx+1]
            # Dijkstra on (person, ship) state
            dist = [[INF]*(N+1) for _ in range(N+1)]
            pq = []
            for s in range(1,N+1):
                if dp[s] < INF:
                    dist[a][s] = dp[s]
                    heappush(pq,(dp[s],a,s))
            while pq:
                d,p,s = heappop(pq)
                if d > dist[p][s]: continue
                for (nb,t) in land_adj[p]:
                    nd=d+t
                    if nd<dist[nb][s]: dist[nb][s]=nd; heappush(pq,(nd,nb,s))
                if p==s:
                    for (nb,t) in sea_adj[p]:
                        nd=d+t
                        if nd<dist[nb][nb]: dist[nb][nb]=nd; heappush(pq,(nd,nb,nb))
            dp2=[INF]*(N+1)
            for s in range(1,N+1):
                if dist[b][s]<dp2[s]: dp2[s]=dist[b][s]
            dp=dp2
        ans=min(dp[1:])
        out_lines.append(str(ans) if ans<INF else 'inf')
    print('\n'.join(out_lines))

if __name__=="__main__":
    solve()

