import sys, math

def find_three_factors(n):
    a = b = c = None
    # find first factor a
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            a = i
            n //= i
            break
    if a is None:
        return None
    # find second factor b
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0 and i != a:
            b = i
            c = n // i
            break
    if b is None or c is None:
        return None
    if c != a and c != b and c > 1:
        return a, b, c
    return None

