def solve():
    input_data = sys.stdin.read().split('\n')
    idx = 0

    while idx < len(input_data):
        line = input_data[idx].strip()
        idx += 1
        if not line:
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        w, h = int(parts[0]), int(parts[1])
        if w == 0 and h == 0:
            break

        grid = []
        for i in range(h):
            while idx < len(input_data):
                row_line = input_data[idx]
                idx += 1
                # Remove trailing whitespace but preserve content
                row_line = row_line.rstrip('\n').rstrip('\r')
                # Split by spaces if needed, but the grid cells are space-separated
                # Actually looking at the input, it seems space separated
                cells = row_line.split()
                if len(cells) == w:
                    grid.append(cells)
                    break
                elif len(cells) == 0:
                    continue
                else:
                    # Maybe it's not space separated, try character by character
                    # Filter only valid characters
                    filtered = [c for c in row_line if c in 'BWb.']
                    # Actually just use the raw chars
                    raw = [c for c in row_line if c != ' ']
                    if len(raw) == w:
                        grid.append(raw)
                        break
                    else:
                        # try splitting anyway
                        grid.append(cells)
                        break

        # BFS/flood fill to determine which grids are extended adjacent to B and W
        # For each empty grid, determine reachability from B stakes and W stakes

        # Create adjacency: 4-directional
        # For each cell, compute set of stake colors reachable

        # We'll do multi-source BFS from B stakes and from W stakes separately

        reach_B = [[False]*w for _ in range(h)]
        reach_W = [[False]*w for _ in range(h)]

        queue_B = deque()
        queue_W = deque()

        for r in range(h):
            for c in range(w):
                cell = grid[r][c] if r < len(grid) and c < len(grid[r]) else '.'
                if cell == 'B':
                    # B stakes spread to adjacent empty cells
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < h and 0 <= nc < w:
                            adj_cell = grid[nr][nc] if nr < len(grid) and nc < len(grid[nr]) else '.'
                            if adj_cell == '.':
                                if not reach_B[nr][nc]:
                                    reach_B[nr][nc] = True
                                    queue_B.append((nr, nc))
                elif cell == 'W':
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < h and 0 <= nc < w:
                            adj_cell = grid[nr][nc] if nr < len(grid) and nc < len(grid[nr]) else '.'
                            if adj_cell == '.':
                                if not reach_W[nr][nc]:
                                    reach_W[nr][nc] = True
                                    queue_W.append((nr, nc))

        # BFS for B
        while queue_B:
            r, c = queue_B.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w:
                    adj_cell = grid[nr][nc] if nr < len(grid) and nc < len(grid[nr]) else '.'
                    if adj_cell == '.' and not reach_B[nr][nc]:
                        reach_B[nr][nc] = True
                        queue_B.append((nr, nc))

        # BFS for W
        while queue_W:
            r, c = queue_W.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w:
                    adj_cell = grid[nr][nc] if nr < len(grid) and nc < len(grid[nr]) else '.'
                    if adj_cell == '.' and not reach_W[nr][nc]:
                        reach_W[nr][nc] = True
                        queue_W.append((nr, nc))

        count_B = 0
        count_W = 0
        for r in range(h):
            for c in range(w):
                cell = grid[r][c] if r < len(grid) and c < len(grid[r]) else '.'
                if cell == '.':
                    if reach_B[r][c] and not reach_W[r][c]:
                        count_B += 1
                    elif reach_W[r][c] and not reach_B[r][c]:
                        count_W += 1

        print(count_B, count_W)

solve()

