import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m = map(int, data[:2])
    if n == 0:
        if m <= 2:
            sys.stdout.write('1' * m)
        else:
            sys.stdout.write('-1')
        return
    min_ones = n - 1
    max_ones = 2 * (n + 1)
    if m < min_ones or m > max_ones:
        sys.stdout.write('-1')
        return
    gaps = [0] * (n + 1)
    for i in range(1, n):
        gaps[i] = 1
    remaining = m - min_ones
    # Fill internal gaps first (indices 1..n-1), then edges (0 and n)
    # Internal gaps already have 1, can add 1 more each
    # Edge gaps have 0, can add up to 2 each
    # Fill internal gaps first
    for i in range(1, n):
        if remaining <= 0:
            break
        add = min(2 - gaps[i], remaining)
        gaps[i] += add
        remaining -= add
    # Then fill edge gaps
    for i in [0, n]:
        if remaining <= 0:
            break
        add = min(2 - gaps[i], remaining)
        gaps[i] += add
        remaining -= add
    # build result
    res_parts = []
    for i in range(n):
        if gaps[i]:
            res_parts.append('1' * gaps[i])
        res_parts.append('0')
    if gaps[n]:
        res_parts.append('1' * gaps[n])
    sys.stdout.write(''.join(res_parts))

if __name__ == "__main__":
    solve()

