import sys

def length_at(poly, x):
    vals = []
    n = len(poly)
    for i in range(n):
        x1, v1 = poly[i]
        x2, v2 = poly[(i + 1) % n]
        if x1 == x2:
            continue
        if (x - x1) * (x - x2) <= 0:
            t = (x - x1) / (x2 - x1)
            vals.append(v1 + t * (v2 - v1))
    if len(vals) < 2:
        return 0.0
    return max(vals) - min(vals)

def area_at(poly1, poly2, x):
    return length_at(poly1, x) * length_at(poly2, x)

def solve():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    out_lines = []
    for m_str in it:
        m = int(m_str); n = int(next(it))
        if m == 0 and n == 0:
            break
        poly1 = [(int(next(it)), int(next(it))) for _ in range(m)]
        poly2 = [(int(next(it)), int(next(it))) for _ in range(n)]

        xs = sorted({x for x, _ in poly1} | {x for x, _ in poly2})

        volume = 0.0
        for i in range(len(xs) - 1):
            x_left, x_right = xs[i], xs[i + 1]
            if x_right - x_left == 0:
                continue
            xm = (x_left + x_right) * 0.5
            fa = area_at(poly1, poly2, x_left)
            fm = area_at(poly1, poly2, xm)
            fb = area_at(poly1, poly2, x_right)
            # Simpson's rule - exact for piecewise quadratic
            volume += (x_right - x_left) / 6.0 * (fa + 4.0 * fm + fb)
        out_lines.append(repr(volume))
    sys.stdout.write("\n".join(out_lines) + "\n")

