def count_sets(n, k, s):
    if k > n or s > 155:
        return 0
    dp = [[0] * (s + 1) for _ in range(k + 1)]
    dp[0][0] = 1
    for num in range(1, n + 1):
        upper_j = min(k, num)
        for j in range(upper_j, 0, -1):
            row_prev = dp[j - 1]
            row_cur = dp[j]
            for t in range(s, num - 1, -1):
