import sys

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    p = [0] + [int(next(it)) for _ in range(n)]
    pos = [0] * (n + 1)
    for i in range(1, n + 1):
        pos[p[i]] = i

    swaps = []

    def do_swap(a: int, b: int) -> None:
        if a == b:
            return
        assert 2 * abs(a - b) >= n
        swaps.append((a, b))
        p[a], p[b] = p[b], p[a]
        pos[p[a]] = a
        pos[p[b]] = b

    half = n // 2

    def smart_swap(i: int, j: int) -> None:
        if i == j:
            return
        if 2 * abs(i - j) >= n:
            do_swap(i, j)
            return
        if i > j:
            i, j = j, i
        # i < j, too close
        if j <= half:
            pivot = n
            do_swap(i, pivot); do_swap(j, pivot); do_swap(i, pivot)
        elif i > half:
            pivot = 1
            do_swap(i, pivot); do_swap(j, pivot); do_swap(i, pivot)
        else:
            # i <= half, j > half, too close
            do_swap(i, n); do_swap(1, j); do_swap(1, n); do_swap(i, n); do_swap(1, j)

    for v in range(1, n + 1):
        while pos[v] != v:
            smart_swap(v, pos[v])

    out = [str(len(swaps))]
    out += [f"{a} {b}" for a, b in swaps]
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

cc_p00907 Find the Outlier.code:
import sys
from itertools import combinations

def solve_system(a, b):
    n = len(a)
    for i in range(n):
        piv = i
        for r in range(i+1, n):
            if abs(a[r][i]) > abs(a[piv][i]):
                piv = r
        if abs(a[piv][i]) < 1e-12:
            return None
        a[i], a[piv] = a[piv], a[i]
        b[i], b[piv] = b[piv], b[i]
        div = a[i][i]
        for c in range(i, n):
            a[i][c] /= div
        b[i] /= div
        for r in range(n):
            if r == i:
                continue
            factor = a[r][i]
            if factor == 0:
                continue
            for c in range(i, n):
                a[r][c] -= factor * a[i][c]
            b[r] -= factor * b[i]
    return b

def poly_coeffs(xs, ys, deg):
    n = deg + 1
    a = [[0.0]*n for _ in range(n)]
    b = [0.0]*n
    for i in range(n):
        x = xs[i]
        powx = 1.0
        for j in range(n):
            a[i][j] = powx
            powx *= x
        b[i] = ys[i]
    return solve_system([row[:] for row in a], b[:])

def evaluate(coeff, x):
    res = 0.0
    powx = 1.0
    for c in coeff:
        res += c * powx
        powx *= x
    return res

data = sys.stdin.read().strip().splitlines()
idx = 0
out = []
while idx < len(data):
    line = data[idx].strip()
    idx += 1
    if line == '':
        continue
    d = int(line)
    if d == 0:
        break
    n = d + 3
    vals = []
    for _ in range(n):
        vals.append(float(data[idx].strip()))
        idx += 1
    bad = -1
    for i in range(n):
        rest = [j for j in range(n) if j != i]
        # Try all combinations of d+1 points from rest to fit polynomial
        found = False
        for subset in combinations(rest, d+1):
            xs = list(subset)
            ys = [vals[x] for x in xs]
            coeff = poly_coeffs(xs, ys, d)
            if coeff is None:
                continue
            ok = True
            for j in rest:
                pred = evaluate(coeff, j)
                if abs(pred - vals[j]) > 1e-3:
                    ok = False
                    break
            if ok:
                found = True
                break
        if found:
            bad = i
            break
    out.append(str(bad))
sys.stdout.write("\n".join(out) + "\n")

