import sys

def point_in_poly(x, y, poly):
    inside = False
    n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        if ((y1 > y) != (y2 > y)):
            xinters = (x2 - x1) * (y - y1) / (y2 - y1) + x1
            if xinters > x:
                inside = not inside
    return inside

def seg_intersects_open_rect(x1, y1, x2, y2, rx, ry):
    # Check if segment intersects open rectangle (rx,rx+1) x (ry,ry+1)
    p = [-(x2 - x1), x2 - x1, -(y2 - y1), y2 - y1]
    q = [x1 - rx, rx + 1 - x1, y1 - ry, ry + 1 - y1]
    u1, u2 = 0.0, 1.0
    for pi, qi in zip(p, q):
        if pi == 0:
            if qi <= 0:
                return False
        else:
            t = qi / pi
            if pi < 0:
                if t > u2:
                    return False
                if t > u1:
                    u1 = t
            else:
                if t < u1:
                    return False
                if t < u2:
                    u2 = t
    if u1 >= u2:
        return False
    return True

def count_squares(poly):
    xs = [p[0] for p in poly]
    ys = [p[1] for p in poly]
    minx, maxx = min(xs), max(xs)
    miny, maxy = min(ys), max(ys)
    cnt = 0
    edges = [(poly[i][0], poly[i][1], poly[(i + 1) % len(poly)][0], poly[(i + 1) % len(poly)][1]) for i in range(len(poly))]
    for y in range(miny, maxy):
        for x in range(minx, maxx):
            if point_in_poly(x + 0.5, y + 0.5, poly):
                cnt += 1
                continue
            for (x1, y1, x2, y2) in edges:
                if seg_intersects_open_rect(x1, y1, x2, y2, x, y):
                    cnt += 1
                    break
    return cnt

def solve():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    out_lines = []
    for token in it:
        m = int(token)
        if m == 0:
            break
        poly = []
        for _ in range(m):
            x = int(next(it))
            y = int(next(it))
            poly.append((x, y))
        out_lines.append(str(count_squares(poly)))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

