import sys

def main():
    data = sys.stdin.read().strip().split()
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    gaps = []
    for i in range(n):
        for j in range(i+1, n):
            gaps.append(abs(a[i] - a[j]))

    max_gap = max(gaps)
    cnt = [0] * (max_gap + 1)
    for g in range(len(gaps)):
        cnt[gaps[g]] += 1

    M = n * (n - 1) // 2
    total = M * M * M

    # suffix[t] = number of gaps strictly greater than t
    suffix = [0] * (2 * max_gap + 2)
    for t in range(2 * max_gap, -1, -1):
        suffix[t] = suffix[t+1] + (cnt[t] if t <= max_gap else 0)

    favorable = 0
    for g1 in range(1, max_gap + 1):
        if cnt[g1] == 0:
            continue
        for g2 in range(1, max_gap + 1):
            if cnt[g2] == 0:
                continue
            s_needed = g1 + g2
            favorable += cnt[g1] * cnt[g2] * suffix[s_needed]

    prob = favorable / total if total != 0 else 0.0
    print("{:.10f}".format(prob))

