import sys

MOD = 1000000007

def z_function(s):
    n = len(s)
    z = [0]*n
    l = r = 0
    for i in range(1, n):
        if i <= r:
            z[i] = min(r - i + 1, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > r:
            l, r = i, i + z[i] - 1
    z[0] = n
    return z

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    p = next(it)
    L = len(p)
    y = [int(next(it)) for _ in range(m)]
    # check overlaps
    if m > 0:
        z = z_function(p)
        for i in range(m-1):
            d = y[i+1] - y[i]
            if d < L:
                if z[d] < L - d:
                    print(0)
                    return
    # count covered positions
    covered = 0
    cur_end = 0
    for pos in y:
        start = pos
        end = pos + L - 1
        if start > cur_end:
            covered += end - start + 1
            cur_end = end
        else:
