cc_p01180 The Closest Circle.code:
import sys
import math

def dist_circles(c1, c2):
    r1, x1, y1 = c1
    r2, x2, y2 = c2
    d = math.sqrt((x1-x2)**2 + (y1-y2)**2)
    return d - r1 - r2

def closest_pair_brute(circles):
    min_d = float('inf')
    n = len(circles)
    for i in range(n):
        for j in range(i+1, n):
            d = dist_circles(circles[i], circles[j])
            if d < min_d:
                min_d = d
    return min_d

def closest_rec(circles_x, start, end, max_r):
    if end - start <= 10:
        return closest_pair_brute(circles_x[start:end])

    mid = (start + end) // 2
    mid_x = circles_x[mid][1]

    dl = closest_rec(circles_x, start, mid, max_r)
    dr = closest_rec(circles_x, mid, end, max_r)
    d = min(dl, dr)

    strip = []
    threshold = d + 2 * max_r
    for i in range(start, end):
        if abs(circles_x[i][1] - mid_x) < threshold:
            strip.append(circles_x[i])

    strip.sort(key=lambda c: c[2])
    n = len(strip)
    min_d = d
    for i in range(n):
        for j in range(i+1, n):
            if (strip[j][2] - strip[i][2]) >= d + 2 * max_r:
                break
            dd = dist_circles(strip[i], strip[j])
            if dd < min_d:
                min_d = dd

    return min_d

def solve(circles):
    n = len(circles)
    if n <= 10:
        return closest_pair_brute(circles)

    max_r = max(c[0] for c in circles)
    sorted_circles = sorted(circles, key=lambda c: c[1])
    return closest_rec(sorted_circles, 0, n, max_r)

def main():
    input_data = sys.stdin.read().split()
    idx = 0

    while idx < len(input_data):
        N = int(input_data[idx])
        idx += 1

        if N == 0:
            break

        circles = []
        for _ in range(N):
            r = float(input_data[idx])
            x = float(input_data[idx+1])
            y = float(input_data[idx+2])
            idx += 3
            circles.append((r, x, y))

        result = solve(circles)
        print(f"{result:.5f}")

main()

