import sys

def can_be_lexico(words):
    # check prefix violation
    for a, b in zip(words, words[1:]):
        if len(a) > len(b) and a.startswith(b):
            return False

    # build graph
    adj = {chr(c): set() for c in range(ord('a'), ord('z')+1)}
    indeg = {chr(c): 0 for c in range(ord('a'), ord('z')+1)}
    present = set()
    for w in words:
        present.update(w)

    for a, b in zip(words, words[1:]):
        # find first differing character
        i = 0
        while i < len(a) and i < len(b) and a[i] == b[i]:
            i += 1
        if i < len(a) and i < len(b):
            u, v = a[i], b[i]
            if v not in adj[u]:
                adj[u].add(v)
                indeg[v] += 1

    # topological sort on present letters
    from collections import deque
    q = deque([c for c in present if indeg[c] == 0])
    visited = 0
    while q:
        u = q.popleft()
        visited += 1
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    return visited == len(present)

def solve():
    data = sys.stdin.read().splitlines()
    out = []
    i = 0
    while i < len(data):
        n = int(data[i].strip())
        i += 1
        if n == 0:
            break
        words = [data[i + j].strip() for j in range(n)]
        i += n
        out.append('yes' if can_be_lexico(words) else 'no')
    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
    solve()

