        arr = []
        xs = []
        for i in range(n):
            token = next(it)
            if token == 'x':
                arr.append(None)
                xs.append(i)
            else:
                arr.append(int(token))
        # check adjacent xs
        impossible = False
        for i in range(n-1):
            if arr[i] is None and arr[i+1] is None:
                impossible = True
                break
        if impossible:
            out_lines.append("none")
            continue
        if not xs:
            # no broken samples, just verify consistency
            ok = True
            for i in range(n):
                if i%2==0:  # index 0 -> sample 1 (odd)
                    if i-1>=0 and not (arr[i] < arr[i-1]): ok=False; break
                    if i+1<n and not (arr[i] < arr[i+1]): ok=False; break
                else:
                    if i-1>=0 and not (arr[i] > arr[i-1]): ok=False; break
                    if i+1<n and not (arr[i] > arr[i+1]): ok=False; break
            out_lines.append("ambiguous" if ok else "none")
            continue
        lower = -INF
        upper = INF
        for i in xs:
            odd = (i % 2 == 0)  # sample number i+1 odd?
            # neighbors
            for nb in (i-1, i+1):
                if 0 <= nb < n and arr[nb] is not None:
                    val = arr[nb]
                    if odd:
                        # v < neighbor
                        upper = min(upper, val - 1)
                    else:
                        # v > neighbor
                        lower = max(lower, val + 1)
        if lower > upper:
            out_lines.append("none")
        elif lower == upper:
            out_lines.append(str(lower))
        else:
