import sys

def digit_mask(x: int) -> int:
    mask = 0
    pos = 0
    if x == 0:
        return 0
    while x:
        if x % 10 != 0:
            mask |= 1 << pos
        x //= 10
        pos += 1
    return mask

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    k = int(data[0])
    nums = list(map(int, data[1:1 + k]))
    masks = [digit_mask(v) for v in nums]

    dp = {0: []}  # mask -> list of indices
    for idx, m in enumerate(masks):
        current_items = list(dp.items())
        for cur_mask, cur_list in current_items:
            if cur_mask & m:
                continue
            new_mask = cur_mask | m
            if len(cur_list) + 1 > len(dp.get(new_mask, [])):
                dp[new_mask] = cur_list + [idx]

    # find best
    best = max(dp.values(), key=len)
    result = sorted([nums[i] for i in best])
    sys.stdout.write(str(len(result)) + "\n")
    sys.stdout.write(" ".join(map(str, result)) + "\n")

if __name__ == "__main__":
    main()

