import sys

def mat_mul(a, b, mod):
    n = len(a)
    m = len(b[0])
    p = len(b)
    res = [[0]*m for _ in range(n)]
    for i in range(n):
        ai = a[i]
        ri = res[i]
        for k in range(p):
            aik = ai[k]
            if aik:
                bk = b[k]
                mul = aik
                for j in range(m):
                    ri[j] = (ri[j] + mul * bk[j]) % mod
    return res

def mat_pow(mat, exp, mod):
    n = len(mat)
    # identity
    res = [[0]*n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1 % mod
    base = mat
    while exp:
        if exp & 1:
            res = mat_mul(res, base, mod)
        base = mat_mul(base, base, mod)
        exp >>= 1
    return res

def solve():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    out_lines = []
    while True:
        try:
            N = int(next(it))
        except StopIteration:
            break
        M = int(next(it)); A = int(next(it)); B = int(next(it)); C = int(next(it)); T = int(next(it))
        if N==0 and M==0 and A==0 and B==0 and C==0 and T==0:
            break
        init = [int(next(it)) % M for _ in range(N)]
        if T == 0:
            out_lines.append(' '.join(str(x) for x in init))
            continue
        # build transition matrix
        tr = [[0]*N for _ in range(N)]
        for i in range(N):
            if i-1 >= 0:
                tr[i][i-1] = A % M
            tr[i][i] = B % M
            if i+1 < N:
                tr[i][i+1] = C % M
        tr_pow = mat_pow(tr, T, M)
        # multiply tr_pow by init vector
        result = []
        for i in range(N):
            s = 0
            row = tr_pow[i]
            for j in range(N):
                s = (s + row[j] * init[j]) % M
            result.append(str(s))
        out_lines.append(' '.join(result))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    solve()

