    segs = [stations[i+1] - stations[i] for i in range(len(stations)-1)]

    def feasible(v):
        total = 0
        for d in segs:
            if v < d:
                return False
            max_acc = min(d, v - d)
            total += 2 * d - max_acc
            if total > t:
                return False
        return total <= t

