import sys
from functools import lru_cache

def solve():
    n = int(input())

    @lru_cache(maxsize=None)
    def max_result(x):
        if x == 1:
            return 1
        best = x + 1  # take 1 pebble (arrange in x rows of 1)
        # find all divisors b of x where a = x/b > 1, i.e. b < x
        i = 2
        while i * i <= x:
            if x % i == 0:
                # b = i (a = x/i rows)
                if x // i > 1:
                    best = max(best, x + max_result(i))
                # b = x//i (a = i rows)
                if i > 1 and x // i != i:
                    best = max(best, x + max_result(x // i))
                elif x // i == i:
                    best = max(best, x + max_result(x // i))
            i += 1
        return best

    print(max_result(n))

solve()

