import sys

def solve():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    t = int(next(it))
    out = []
    for _ in range(t):
        n = int(next(it)); m = int(next(it)); k = int(next(it))
        edges = []
        max_lt = -1
        for _ in range(m):
            x = int(next(it)); y = int(next(it)); s = int(next(it))
            w = s - k if s > k else 0
            edges.append((w, s, x-1, y-1))
            if s < k and s > max_lt:
                max_lt = s
        edges.sort(key=lambda e: e[0])
        parent = list(range(n))
        rank = [0]*n
        def find(a):
            while parent[a]!=a:
                parent[a]=parent[parent[a]]
                a=parent[a]
            return a
        def union(a,b):
            ra, rb = find(a), find(b)
            if ra==rb: return False
            if rank[ra]<rank[rb]:
                parent[ra]=rb
            elif rank[ra]>rank[rb]:
                parent[rb]=ra
            else:
                parent[rb]=ra
                rank[ra]+=1
            return True
        total = 0
        has_ge = False
        cnt = 0
        max_s_in_tree = -1
        for w,s,x,y in edges:
            if union(x,y):
                total += w
                if s >= k:
                    has_ge = True
                if s < k and s > max_s_in_tree:
                    max_s_in_tree = s
                cnt += 1
                if cnt == n-1:
                    break
        if has_ge:
            out.append(str(total))
        else:
            add = k - max_lt
            out.append(str(total + add))
    sys.stdout.write("\n".join(out) + "\n")

