import sys

def solve():
    data = sys.stdin.read().splitlines()
    i = 0
    out = []
    while i < len(data):
        line = data[i].strip()
        i += 1
        if line == '0' or line == '':
            break
        n = int(line)
        cand = []
        for _ in range(n):
            cand.append(data[i].strip())
            i += 1
        seq_line = data[i].strip()
        i += 1
        # parse ciphertext words (remove trailing period)
        seq_line = seq_line.rstrip('.')
        cipher_words = seq_line.split(' ')
        L = len(cipher_words)

        # Precompute candidates by length
        cand_by_len = {}
        for w in cand:
            cand_by_len.setdefault(len(w), []).append(w)

        solutions = []
        mapping = {}  # cipher->plain
        revmap = {}   # plain->cipher

        def backtrack(idx, plain_seq):
            if len(solutions) > 1:
                return
            if idx == L:
                solutions.append(' '.join(plain_seq) + '.')
                return
            cw = cipher_words[idx]
            possible = cand_by_len.get(len(cw), [])
            for pw in possible:
                # try match cw -> pw
                saved = []
                ok = True
                for a, b in zip(cw, pw):
                    ma = mapping.get(a)
                    mb = mapping.get(b)
                    # need symmetric mapping a<->b
                    if ma is None and mb is None:
                        # assign
                        if a == b:
                            mapping[a] = a
                            saved.append((a, None))
                        else:
                            mapping[a] = b
                            mapping[b] = a
                            saved.append((a, None))
                            saved.append((b, None))
                    else:
                        # check consistency
                        if ma is not None:
                            if ma != b:
                                ok = False
                                break
                        if mb is not None:
                            if mb != a:
                                ok = False
                                break
                        # also ensure symmetric already holds (it does by construction)
                if ok:
                    backtrack(idx+1, plain_seq + [pw])
                # undo
                for key, _ in reversed(saved):
                    del mapping[key]

        backtrack(0, [])
        if len(solutions) == 1:
            out.append(solutions[0])
        else:
            out.append('-.')
    sys.stdout.write('\n'.join(out))

