import sys
from collections import deque

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    dist = [-1]*n
    res = a[:]
    q = deque()
    for i in range(n):
        stable = False
        if i == 0 or i == n-1:
            stable = True
        else:
            if a[i] == a[i-1] or a[i] == a[i+1]:
                stable = True
        if stable:
            dist[i] = 0
            q.append(i)
    while q:
        i = q.popleft()
        for nb in (i-1, i+1):
            if 0 <= nb < n and dist[nb] == -1:
                dist[nb] = dist[i] + 1
                res[nb] = res[i]
                q.append(nb)
    max_dist = max(dist)
    out = [str(max_dist), "\n", " ".join(map(str, res))]
    sys.stdout.write("".join(out))

