import sys

sys.setrecursionlimit(10000)
INF = 10**9

def vc(edges, k):
    if not edges:
        return 0
    if k == 0:
        return INF
    deg = {}
    for u, v in edges:
        deg[u] = deg.get(u, 0) + 1
        deg[v] = deg.get(v, 0) + 1
    for v, d in deg.items():
        if d > k:
            new_edges = [e for e in edges if v not in e]
            sub = vc(new_edges, k - 1)
            return INF if sub == INF else sub + 1
    u, v = edges[0]
    edges_u = [e for e in edges if u not in e]
    res_u = vc(edges_u, k - 1)
    if res_u != INF:
        res_u += 1
    edges_v = [e for e in edges if v not in e]
    res_v = vc(edges_v, k - 1)
    if res_v != INF:
        res_v += 1
    return res_u if res_u < res_v else res_v

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    K = int(next(it))
    edges = []
    for _ in range(m):
        a = int(next(it))
        b = int(next(it))
        edges.append((a, b))
    ans = vc(edges, K)
    if ans == INF or ans > K:
        print("Impossible")
    else:
        print(ans)

if __name__ == "__main__":
    main()

