import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, k = map(int, data)
    size = n + 2
    bit = [0] * size

    def add(idx, val=1):
        while idx < size:
            bit[idx] += val
            idx += idx & -idx

    def sum_prefix(idx):
        s = 0
        while idx > 0:
            s += bit[idx]
            idx -= idx & -idx
        return s

    def range_sum(l, r):
        if l > r:
            return 0
        return sum_prefix(r) - sum_prefix(l - 1)

    regions = 1
    out = []
    for i in range(1, n + 1):
        j = i + k
        if j <= n:
            cnt = range_sum(i + 1, j - 1)
        else:
            j -= n
            cnt = range_sum(i + 1, n) + range_sum(1, j - 1)
        regions += 1 + cnt
        out.append(str(regions))
        add(i, 1)
    sys.stdout.write(' '.join(out))

if __name__ == "__main__":
    solve()

