def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    x = int(data[1])
    steps = n % 6  # period of the sequence
    for init in range(3):
        pos = init
        for i in range(1, steps + 1):
            if i & 1:  # odd move: swap 0 and 1
                if pos == 0:
                    pos = 1
                elif pos == 1:
                    pos = 0
            else:      # even move: swap 1 and 2
                if pos == 1:
                    pos = 2
                elif pos == 2:
                    pos = 1
        if pos == x:
            print(init)
            return

