import sys

def solve():
    for line in sys.stdin:
        line = line.strip()
        if line == '#':
            break
        f = line

        possible_outputs = set(int(f[i]) for i in range(128))

        idempotent = True
        for i in range(128):
            bits = [(i >> j) & 1 for j in range(7)]
            if all(b in possible_outputs for b in bits):
                center = bits[3]
                result = int(f[i])
                if result != center:
                    idempotent = False
                    break

        print("yes" if idempotent else "no")

