import sys

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    res0 = 0
    res1 = 1023
    idx = 1
    for _ in range(n):
        op = data[idx].decode(); idx += 1
        v = int(data[idx]); idx += 1
        if op == '&':
            res0 &= v; res1 &= v
        elif op == '|':
            res0 |= v; res1 |= v
        else:
            res0 ^= v; res1 ^= v
    and_mask = 1023
    or_mask = 0
    xor_mask = 0
    for i in range(10):
        b0 = (res0 >> i) & 1
        b1 = (res1 >> i) & 1
        if b0 == 0 and b1 == 0:
            and_mask &= ~(1 << i)
        elif b0 == 1 and b1 == 1:
            or_mask |= (1 << i)
        elif b0 == 1 and b1 == 0:
            xor_mask |= (1 << i)
    and_mask &= 1023
    cmds = []
    if and_mask != 1023:
        cmds.append(('&', and_mask))
    if or_mask != 0:
        cmds.append(('|', or_mask))
    if xor_mask != 0:
        cmds.append(('^', xor_mask))
    out = [str(len(cmds))]
    out += [f"{c} {v}" for c, v in cmds]
    print("\n".join(out))

if __name__ == "__main__":
