import sys
from collections import defaultdict
import heapq

def main():
    data = sys.stdin.read().split()
    idx = 0
    n, k = int(data[idx]), int(data[idx+1])
    idx += 2
    starts = []
    for i in range(n):
        starts.append(data[idx]); idx += 1

    # Read routes
    graph = defaultdict(list)  # city -> [(cost, neighbor)]

    while idx < len(data):
        m = int(data[idx]); idx += 1
        cities = []
        for i in range(m):
            cities.append(data[idx]); idx += 1
        prices = []
        for i in range(m-1):
            prices.append(int(data[idx])); idx += 1
        # Build cumulative costs from each end
        for i in range(m):
            cum = 0
            for j in range(i+1, m):
                cum += prices[j-1]
                graph[cities[i]].append((cum, cities[j]))
            cum = 0
            for j in range(i-1, -1, -1):
                cum += prices[j]
                graph[cities[i]].append((cum, cities[j]))

    def dijkstra(start):
        dist = {start: 0}
        pq = [(0, start)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist.get(u, float('inf')): continue
            for cost, v in graph[u]:
                nd = d + cost
                if nd < dist.get(v, float('inf')):
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
        return dist

    dists = [dijkstra(s) for s in starts]

    all_cities = set(graph.keys())
    for d in dists:
        all_cities |= set(d.keys())

    best_cost = float('inf')
    best_city = None

    for city in sorted(all_cities):
        total = sum(d.get(city, float('inf')) for d in dists)
        if total < best_cost or (total == best_cost and (best_city is None or city < best_city)):
            best_cost = total
            best_city = city

    if best_cost == float('inf'):
        print(-1)
    else:
        print(best_cost, best_city)

if __name__ == "__main__":
    main()

cc_p00546 Zombie Island.code:
import sys, heapq

def solve() -> None:
    data = list(map(int, sys.stdin.read().split()))
    it = iter(data)
    N = next(it); M = next(it); K = next(it); S = next(it)
    P = next(it); Q = next(it)
    zombie = [False]*(N+1)
    zombie_nodes = []
    for _ in range(K):
        c = next(it)
        zombie[c] = True
        zombie_nodes.append(c)
    adj = [[] for _ in range(N+1)]
    for _ in range(M):
        a = next(it); b = next(it)
        adj[a].append(b)
        adj[b].append(a)

    # multi-source BFS for distances from zombie towns
    from collections import deque
    INF = 10**9
    dist = [INF]*(N+1)
    dq = deque()
    for z in zombie_nodes:
        dist[z] = 0
        dq.append(z)
    while dq:
        u = dq.popleft()
        if dist[u] == S:  # no need to expand further
            continue
        nd = dist[u] + 1
        for v in adj[u]:
            if dist[v] > nd:
                dist[v] = nd
                dq.append(v)

    dangerous = [False]*(N+1)
    for i in range(1, N+1):
        if not zombie[i] and dist[i] <= S:
            dangerous[i] = True

    cost = [0]*(N+1)
    for i in range(1, N+1):
        if i == N or i == 1:
            cost[i] = 0
        elif dangerous[i]:
            cost[i] = Q
        else:
            cost[i] = P

    # Dijkstra
    dist2 = [10**30]*(N+1)
    dist2[1] = 0
    heap = [(0,1)]
    while heap:
        d,u = heapq.heappop(heap)
        if d!=dist2[u]:
            continue
        if u==N:
            break
        for v in adj[u]:
            if zombie[v]:
                continue
            nd = d + cost[v]
            if nd < dist2[v]:
                dist2[v] = nd
                heapq.heappush(heap,(nd,v))
    print(dist2[N])

if __name__ == "__main__":
    solve()
